use std::mem::size_of;

fn main() {
    let ok = true;
    let c = 'z';
    let z = 'ℤ';
    let n = size_of::<char>();
    println!("{ok} {c} {z} {n}");
}

fn main() {
    let x: u8 = 255;
    let y = x + 1;
    println!("{y}");
}

fn main() {
    let x: u8 = 255;
    let a = x.checked_add(1);
    let b = x.wrapping_add(1);
    let c = x.saturating_add(1);
    println!("{a:?} {b} {c}");
}
